<template><span class="answer-speech"><button v-if="status !== 'playing' && status !== 'loading'" type="button" :disabled="blocked" @click="play">{{ job?.status === 'completed' ? '重播' : '朗读' }}</button><button v-else type="button" @click="stop">{{ status === 'loading' ? '取消朗读' : '停止朗读' }}</button><small v-if="blocked">通话期间暂停朗读</small><small v-else-if="status === 'error'" role="alert">朗读不可用，请重试</small></span></template>
<script>
import playback from '../speech/answerSpeech.mjs';
export default {name:'AnswerSpeech',props:{conversationId:{type:String,required:true},message:{type:Object,required:true},identity:{type:String,required:true},blocked:{type:Boolean,default:false}},data:()=>({status:'idle',job:null}),computed:{scope(){return JSON.stringify([this.identity,this.conversationId,this.message.id]);},version(){return JSON.stringify([this.message.status,this.message.parts]);}},watch:{blocked:{flush:'sync',handler(value){if(value){playback.invalidate(this.scope);this.status='idle';}}},scope:{flush:'sync',handler(value,old){playback.invalidate(old);this.job=null;this.status='idle';}},version:{flush:'sync',handler(){playback.invalidate(this.scope);this.job=null;this.status='idle';}}},beforeUnmount(){playback.invalidate(this.scope);},methods:{play(){if(this.blocked)return;playback.start({cid:this.conversationId,mid:this.message.id,scope:this.scope,version:this.version,job:this.job,changed:state=>{this.status=state.status;this.job=state.job;}});},stop(){playback.stop();}}};
</script>
<style scoped>.answer-speech{margin-left:8px}.answer-speech button{border:0;background:none;color:#21834c;cursor:pointer}.answer-speech button:disabled{opacity:.5;cursor:default}.answer-speech small{color:#ae463c;margin-left:4px}</style>
